// Master-data record (outside ReDriveBattleCore): Network.Definition.QuestOutGame.BreakMstRecord, generated by scripts/engine/gen_records.py.
// One row of src/assets/base_data/getBreakMstList.json (same keys).

import type { int } from "../../../runtime";

export interface BreakMstRecord {
    /** 0x10 int */
    breakMstId: int;
    /** 0x14 int */
    breakPoint: int;
    /** 0x18 int */
    breakPointRecoveryPerTurn: int;
    /** 0x1c int */
    breakTurnGaugeSlowRatio: int;
    /** 0x20 int */
    initialBreakedDamageReceiveRate: int;
    /** 0x24 int */
    maxBreakedDamageReceiveRate: int;
    /** 0x28 int */
    breakedDamageReceiveRateIncreaseRate: int;
}
